DROP DATABASE IF EXISTS w11_movielens;
CREATE DATABASE w11_movielens CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE w11_movielens;

CREATE TABLE `movie` (
  `movie_id` INT NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `release_year` INT DEFAULT NULL,
  PRIMARY KEY (`movie_id`),
  KEY `idx_movie_year` (`release_year`),
  KEY `idx_movie_title` (`title`)
) ENGINE=InnoDB;

CREATE TABLE `genre` (
  `genre_id` INT NOT NULL,
  `genre_name` VARCHAR(64) NOT NULL,
  PRIMARY KEY (`genre_id`),
  UNIQUE KEY `uk_genre_name` (`genre_name`)
) ENGINE=InnoDB;

CREATE TABLE `movie_genre` (
  `movie_id` INT NOT NULL,
  `genre_id` INT NOT NULL,
  PRIMARY KEY (`movie_id`, `genre_id`),
  KEY `idx_mg_genre` (`genre_id`),
  CONSTRAINT `fk_mg_movie` FOREIGN KEY (`movie_id`) REFERENCES `movie` (`movie_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mg_genre` FOREIGN KEY (`genre_id`) REFERENCES `genre` (`genre_id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `rating` (
  `user_id` INT NOT NULL,
  `movie_id` INT NOT NULL,
  `rating` DECIMAL(2,1) NOT NULL,
  `rated_at` DATETIME NOT NULL,
  PRIMARY KEY (`user_id`, `movie_id`),
  KEY `idx_rating_movie` (`movie_id`),
  KEY `idx_rating_rated_at` (`rated_at`),
  CONSTRAINT `fk_rating_movie` FOREIGN KEY (`movie_id`) REFERENCES `movie` (`movie_id`) ON DELETE CASCADE,
  CONSTRAINT `chk_rating_range` CHECK (`rating` >= 0.5 AND `rating` <= 5.0)
) ENGINE=InnoDB;

CREATE TABLE `movie_tag` (
  `tag_id` INT NOT NULL AUTO_INCREMENT,
  `user_id` INT NOT NULL,
  `movie_id` INT NOT NULL,
  `tag` VARCHAR(150) NOT NULL,
  `tagged_at` DATETIME NOT NULL,
  PRIMARY KEY (`tag_id`),
  KEY `idx_tag_movie` (`movie_id`),
  KEY `idx_tag_text` (`tag`),
  CONSTRAINT `fk_tag_movie` FOREIGN KEY (`movie_id`) REFERENCES `movie` (`movie_id`) ON DELETE CASCADE
) ENGINE=InnoDB;









































































































